test('mergeCustomers removes duplicate customer', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, customers.length - 1);
  assert.ok(!result.value.customers.find((c) => c.id === 'C-001'));
  assert.ok(result.value.customers.find((c) => c.id === 'C-002'));
});

test('mergeCustomers reassigns invoices to new customer', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', number: 'INV-2024-0001', status: 'issued' },
    { customerId: 'C-001', number: 'INV-2024-0002', status: 'paid' },
    { customerId: 'C-002', number: 'INV-2024-0003', status: 'issued' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
  assert.equal(result.value.invoices[2].customerId, 'C-002');
});

test('mergeCustomers rejects same customer', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-001');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers rejects unknown fromId', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-999', 'C-001');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers rejects unknown intoId', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-999');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers preserves invoice data except customerId', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', number: 'INV-2024-0001', status: 'issued', issueDate: '2024-01-15' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  const mergedInvoice = result.value.invoices[0];
  assert.equal(mergedInvoice.customerId, 'C-002');
  assert.equal(mergedInvoice.number, 'INV-2024-0001');
  assert.equal(mergedInvoice.status, 'issued');
  assert.equal(mergedInvoice.issueDate, '2024-01-15');
});

test('mergeCustomers does not mutate original arrays', () => {
  const customers = listCustomers();
  const originalCustomerCount = customers.length;
  const invoices = [{ customerId: 'C-001' }];
  const originalInvoices = [...invoices];

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(customers.length, originalCustomerCount);
  assert.equal(invoices[0].customerId, 'C-001');
});

test('mergeCustomers with normalized IDs', () => {
  const customers = listCustomers();
  const invoices = [{ customerId: 'C-001', number: 'INV-001' }];

  const result = mergeCustomers(customers, invoices, '  c-001  ', '  c-002  ');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.ok(!result.value.customers.find((c) => c.id === 'C-001'));
});

test('mergeCustomers with empty invoices array', () => {
  const customers = listCustomers();

  const result = mergeCustomers(customers, [], 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.customers.length, customers.length - 1);
});

test('mergeCustomers with multiple invoices from different customers', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', id: '1' },
    { customerId: 'C-002', id: '2' },
    { customerId: 'C-001', id: '3' },
    { customerId: 'C-003', id: '4' },
    { customerId: 'C-001', id: '5' },
  ];

