import test from 'node:test';
import assert from 'node:assert/strict';
import { getCustomer, listCustomers, validateCustomer, normalizeId, mergeCustomers } from '../src/customers.js';

test('getCustomer finds a customer by id', () => {
  const r = getCustomer('C-003');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Kite & Co');
});

test('getCustomer reports an unknown id', () => {
  assert.deepEqual(getCustomer('C-999'), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('every customer has a tier', () => {
  for (const c of listCustomers()) assert.ok(['gold', 'silver', 'standard'].includes(c.tier), c.id);
});

test('validateCustomer needs an id, a name and an email', () => {
  assert.equal(validateCustomer({ id: 'C-100', name: 'X', email: 'x@y.example' }).ok, true);
  assert.deepEqual(validateCustomer({ id: 'C-100', name: 'X', email: 'nope' }), { ok: false, error: 'CUSTOMER_INVALID' });
});

test('normalizeId trims whitespace', () => {
  assert.equal(normalizeId('  C-003  '), 'C-003');
  assert.equal(normalizeId('C-003\t'), 'C-003');
  assert.equal(normalizeId('\nC-003'), 'C-003');
});

test('normalizeId converts to uppercase', () => {
  assert.equal(normalizeId('c-003'), 'C-003');
  assert.equal(normalizeId('C-003'), 'C-003');
  assert.equal(normalizeId('c-007'), 'C-007');
});

test('normalizeId trims and uppercases together', () => {
  assert.equal(normalizeId('  c-003  '), 'C-003');
  assert.equal(normalizeId('\tc-007\n'), 'C-007');
});

test('getCustomer works with lowercase id', () => {
  const r = getCustomer('c-003');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Kite & Co');
});

test('getCustomer works with id with spaces', () => {
  const r = getCustomer('  C-003  ');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Kite & Co');
});

test('getCustomer works with mixed case and spaces', () => {
  const r = getCustomer('  c-007  ');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Halvorsen Architects');
});

test('mergeCustomers removes duplicate customer', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, customers.length - 1);
  assert.ok(!result.value.customers.find((c) => c.id === 'C-001'));
  assert.ok(result.value.customers.find((c) => c.id === 'C-002'));
});

test('mergeCustomers reassigns invoices to new customer', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', number: 'INV-2024-0001', status: 'issued' },
    { customerId: 'C-001', number: 'INV-2024-0002', status: 'paid' },
    { customerId: 'C-002', number: 'INV-2024-0003', status: 'issued' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
  assert.equal(result.value.invoices[2].customerId, 'C-002');
});

test('mergeCustomers rejects same customer', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-001');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers rejects unknown fromId', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-999', 'C-001');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers rejects unknown intoId', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-999');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers preserves invoice data except customerId', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', number: 'INV-2024-0001', status: 'issued', issueDate: '2024-01-15' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  const mergedInvoice = result.value.invoices[0];
  assert.equal(mergedInvoice.customerId, 'C-002');
  assert.equal(mergedInvoice.number, 'INV-2024-0001');
  assert.equal(mergedInvoice.status, 'issued');
  assert.equal(mergedInvoice.issueDate, '2024-01-15');
});

test('mergeCustomers does not mutate original arrays', () => {
  const customers = listCustomers();
  const originalCustomerCount = customers.length;
  const invoices = [{ customerId: 'C-001' }];
  const originalInvoices = [...invoices];

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(customers.length, originalCustomerCount);
  assert.equal(invoices[0].customerId, 'C-001');
});

test('mergeCustomers with normalized IDs', () => {
  const customers = listCustomers();
  const invoices = [{ customerId: 'C-001', number: 'INV-001' }];

  const result = mergeCustomers(customers, invoices, '  c-001  ', '  c-002  ');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.ok(!result.value.customers.find((c) => c.id === 'C-001'));
});

test('mergeCustomers with empty invoices array', () => {
  const customers = listCustomers();

  const result = mergeCustomers(customers, [], 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.customers.length, customers.length - 1);
});

test('mergeCustomers with multiple invoices from different customers', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', id: '1' },
    { customerId: 'C-002', id: '2' },
    { customerId: 'C-001', id: '3' },
    { customerId: 'C-003', id: '4' },
    { customerId: 'C-001', id: '5' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  const c001Invoices = result.value.invoices.filter((inv) => invoices.find((i) => i.id === inv.id && i.customerId === 'C-001'));
  assert.equal(c001Invoices.length, 0);

  const c002Invoices = result.value.invoices.filter((inv) => invoices.find((i) => i.id === inv.id) && inv.customerId === 'C-002');
  assert.equal(c002Invoices.length, 3);
});

test('mergeCustomers preserves other customer invoices', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', id: '1' },
    { customerId: 'C-002', id: '2' },
    { customerId: 'C-003', id: '3' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  const result2 = result.value.invoices.find((inv) => inv.id === '2');
  const result3 = result.value.invoices.find((inv) => inv.id === '3');
  assert.equal(result2.customerId, 'C-002');
  assert.equal(result3.customerId, 'C-003');
});

test('mergeCustomers case insensitive same customer check', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'c-001', 'C-001');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers returns new objects', () => {
  const customers = listCustomers();
  const c001 = customers.find((c) => c.id === 'C-001');
  const invoices = [{ customerId: 'C-001', number: 'INV-001' }];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  const originalInvoices = result.value.invoices;
  const newC002 = result.value.customers.find((c) => c.id === 'C-002');

  // Verify original customer still exists in original array
  assert.equal(customers.find((c) => c.id === 'C-001').id, 'C-001');

  // Verify invoice was copied, not mutated
  assert.notEqual(invoices[0], originalInvoices[0]);
});

